// @ts-check
/**
 * The published assets and their checksum manifest (REQ-STARTUP-031, REQ-STARTUP-032, REQ-STARTUP-152;
 * first-release-plan.md §4.7; ADR-0054's Decision: "the checksums manifest is generated by the release pipeline from
 * the emitted assets").
 *
 * A release directory holds what the release publishes and nothing else: the artifacts of the published platform set,
 * named by `tools/release-naming` alone, `SHA256SUMS.txt` over them, and `SHA256SUMS.txt.sig` over that. The manifest's
 * format is the naming authority's (`formatChecksumManifest`), the same text the updater parses, so the writer here
 * composes no line of its own.
 *
 * Plain JavaScript with no installed dependency, on purpose: the signing job runs this tool without `pnpm install`, so
 * the only modules it reaches are Node's own and two TypeScript files of erasable syntax loaded by Node's type stripping
 * (the naming authority, and the updater's key set in `signing.mjs`).
 */
import { createHash } from 'node:crypto';
import { closeSync, existsSync, openSync, readdirSync, readFileSync, readSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  artifactName,
  CHECKSUM_MANIFEST_NAME,
  CHECKSUM_SIGNATURE_NAME,
  formatChecksumManifest,
  KINDS_BY_PLATFORM,
  parseChecksumManifest,
} from '../release-naming/src/index.ts';

/**
 * The platform keys a release publishes for: `windows-x64` alone while `PD-STARTUP-001` stands. Withdrawing the
 * directive is the one change that widens this list (and the workflow's matrix), and it lands only once IC-3 and IC-8
 * are discharged.
 */
export const PUBLISHED_PLATFORMS = Object.freeze(['windows-x64']);

/** Every artifact a release of `version` publishes for `platforms`, named by the authority, in matrix order. */
export function expectedAssets(version, platforms = PUBLISHED_PLATFORMS) {
  return platforms.flatMap((platform) => {
    const kinds = KINDS_BY_PLATFORM[/** @type {keyof typeof KINDS_BY_PLATFORM} */ (platform)];
    if (!kinds) throw new Error(`"${platform}" is not a platform key of REQ-STARTUP-030`);
    return kinds.map((kind) => ({ platform, kind, name: artifactName(version, kind) }));
  });
}

/** The SHA-256 of a file in lower-case hexadecimal, read 1 MiB at a time so an installer is never held whole. */
export function sha256File(path) {
  const hash = createHash('sha256');
  const chunk = Buffer.allocUnsafe(1024 * 1024);
  const fd = openSync(path, 'r');
  try {
    for (;;) {
      const read = readSync(fd, chunk, 0, chunk.length, null);
      if (read === 0) break;
      hash.update(chunk.subarray(0, read));
    }
  } finally {
    closeSync(fd);
  }
  return hash.digest('hex');
}

/**
 * What a release directory holds, read against the names the authority renders: the assets it expects and found, the
 * ones it expects and did not find, and every other file. The manifest and its signature are neither asset nor foreign.
 */
export function readReleaseDirectory(dir, version, platforms = PUBLISHED_PLATFORMS) {
  const expected = expectedAssets(version, platforms);
  const present = new Set(readdirSync(dir).filter((name) => statSync(join(dir, name)).isFile()));
  const assets = expected.filter((a) => present.has(a.name));
  const missing = expected.filter((a) => !present.has(a.name));
  const known = new Set([...expected.map((a) => a.name), CHECKSUM_MANIFEST_NAME, CHECKSUM_SIGNATURE_NAME]);
  const foreign = [...present].filter((name) => !known.has(name)).sort();
  return { assets, missing, foreign };
}

function foreignProblems(foreign, version) {
  return foreign.map((name) => `REQ-STARTUP-152: "${name}" is not an artifact name tools/release-naming renders for ${version}; a release publishes nothing the naming scheme does not name`);
}

/**
 * REQ-STARTUP-032: writes `SHA256SUMS.txt` into `dir` over every asset the directory holds — never itself, never the
 * signature — and removes any earlier signature, which was made over other bytes. A file the naming scheme does not name
 * refuses the step with nothing written. An expected asset that is absent is not this step's refusal: the manifest
 * covers what the release publishes, and `verifyReleaseDirectory` is where an incomplete release fails.
 */
export function writeChecksumManifest(dir, version, platforms = PUBLISHED_PLATFORMS) {
  const { assets, foreign } = readReleaseDirectory(dir, version, platforms);
  if (foreign.length > 0) return { ok: false, problems: foreignProblems(foreign, version) };
  if (assets.length === 0) return { ok: false, problems: [`REQ-STARTUP-032: ${dir} holds no artifact of ${version} to list`] };
  const entries = assets.map((a) => ({ name: a.name, sha256: sha256File(join(dir, a.name)) }));
  const text = formatChecksumManifest(entries);
  writeFileSync(join(dir, CHECKSUM_MANIFEST_NAME), text);
  rmSync(join(dir, CHECKSUM_SIGNATURE_NAME), { force: true });
  return { ok: true, entries: parseChecksumManifest(text), text };
}

/**
 * The checksum half of §5's gate ("`SHA256SUMS.txt` covers every asset, and every digest matches"): every problem, none
 * when the directory is a complete release of `version` whose manifest is the authority's exact rendering of its
 * assets. The signature half is `verifyReleaseSignature` (`signing.mjs`).
 */
export function verifyReleaseDirectory(dir, version, platforms = PUBLISHED_PLATFORMS) {
  const problems = [];
  const { assets, missing, foreign } = readReleaseDirectory(dir, version, platforms);
  for (const a of missing) {
    const why = a.kind === 'portable' ? ' (the portable is assembled around the launcher stub of first-release-plan.md §4.5)' : '';
    problems.push(`REQ-STARTUP-031: ${a.name} is missing; ${a.platform} publishes ${KINDS_BY_PLATFORM[/** @type {keyof typeof KINDS_BY_PLATFORM} */ (a.platform)].join(' and ')}${why}`);
  }
  problems.push(...foreignProblems(foreign, version));
  const manifestPath = join(dir, CHECKSUM_MANIFEST_NAME);
  if (!existsSync(manifestPath)) {
    problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} is missing; a release publishing no manifest is refused as unverifiable`);
    return problems;
  }
  const text = readFileSync(manifestPath, 'utf8');
  const listed = parseChecksumManifest(text);
  if (formatChecksumManifest(listed) !== text) {
    problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} is not in the one format (one "<sha256>  <filename>" line per asset, lower-case digest, two spaces, sorted by filename, LF)`);
  }
  const byName = new Map(listed.map((e) => [e.name, e.sha256]));
  for (const self of [CHECKSUM_MANIFEST_NAME, CHECKSUM_SIGNATURE_NAME]) {
    if (byName.has(self)) problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} lists ${self}; it lists neither itself nor the signature`);
  }
  for (const a of assets) {
    const want = byName.get(a.name);
    if (want === undefined) problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} does not list ${a.name}`);
    else if (want !== sha256File(join(dir, a.name))) problems.push(`REQ-STARTUP-032: the digest ${CHECKSUM_MANIFEST_NAME} lists for ${a.name} does not match the file`);
  }
  const held = new Set(assets.map((a) => a.name));
  for (const name of byName.keys()) {
    if (name === CHECKSUM_MANIFEST_NAME || name === CHECKSUM_SIGNATURE_NAME) continue;
    if (!held.has(name)) problems.push(`REQ-STARTUP-032: ${CHECKSUM_MANIFEST_NAME} lists ${name}, which the release does not publish`);
  }
  return problems;
}
